import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"dev/getting-started/configuration.md","filePath":"dev/getting-started/configuration.md"}'),r={name:"dev/getting-started/configuration.md"};function n(i,e,s,c,h,l){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Copy <code>.env.example</code> to <code>.env</code> and set the values below. Only the keys that matter for this platform are listed; the rest are standard Laravel.</p><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to &quot;Application&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>APP_URL</code></td><td>Public URL. Used in links and media URLs.</td></tr><tr><td><code>APP_LOCALE</code>, <code>APP_FALLBACK_LOCALE</code></td><td>Default language (<code>en</code> or <code>ar</code>). Client requests override it with <code>Accept-Language</code>.</td></tr><tr><td><code>QUEUE_CONNECTION</code></td><td>Queues are required: notifications, exports, WhatsApp and money listeners run queued.</td></tr><tr><td><code>CACHE_STORE</code></td><td>Used for the home payload and the promotions cache. Use a store shared by all workers in production.</td></tr><tr><td><code>FILESYSTEM_DISK</code>, <code>AWS_*</code></td><td>Media and export storage.</td></tr></tbody></table><h2 id="seeded-super-admin" tabindex="-1">Seeded super admin <a class="header-anchor" href="#seeded-super-admin" aria-label="Permalink to &quot;Seeded super admin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>SUPER_ADMIN_NAME</code>, <code>SUPER_ADMIN_EMAIL</code>, <code>SUPER_ADMIN_PASSWORD</code></td><td>The first system user, created by the seeder with all permissions.</td></tr></tbody></table><h2 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PURCHASE_GATEWAY</code></td><td>Which gateway the checkout uses.</td></tr><tr><td><code>MOYASAR_PUBLISHABLE_KEY</code>, <code>MOYASAR_SECRET_KEY</code>, <code>MOYASAR_WEBHOOK_SECRET</code></td><td>Moyasar credentials. Webhooks arrive at <code>POST /api/v1/webhooks/moyasar</code>.</td></tr><tr><td><code>MOYASAR_APPLE_PAY_*</code></td><td>Apple Pay options for Moyasar.</td></tr><tr><td><code>TAMARA_API_TOKEN</code>, <code>TAMARA_NOTIFICATION_TOKEN</code></td><td>Tamara credentials. Webhooks arrive at <code>POST /api/v1/webhooks/tamara</code>.</td></tr></tbody></table><p>Never log secrets and never send card data through the backend. See <a href="./../domain/purchase">Purchases and payments</a>.</p><h2 id="messaging" tabindex="-1">Messaging <a class="header-anchor" href="#messaging" aria-label="Permalink to &quot;Messaging&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>FIREBASE_CREDENTIALS</code></td><td>Service account for push notifications (FCM).</td></tr><tr><td><code>VOXA_*</code></td><td>WhatsApp provider used by notification campaigns.</td></tr><tr><td><code>MAIL_*</code></td><td>Outgoing mail.</td></tr></tbody></table><h2 id="otp-development-bypass" tabindex="-1">OTP development bypass <a class="header-anchor" href="#otp-development-bypass" aria-label="Permalink to &quot;OTP development bypass&quot;">​</a></h2><p>Phone login uses one-time codes. A bypass for developers exists, but it works only when <code>otp.dev.enabled</code> is on, the environment is <code>local</code>, <code>testing</code> or <code>staging</code>, and the phone number is listed in <code>OTP_DEV_PHONES</code>. Never enable it in production. See <a href="./../domain/support">Support</a>.</p>',13)])])}const _=t(r,[["render",n]]);export{u as __pageData,_ as default};
